{ arg out=0, freq=440, amp=0.1, gate=1, dec=0.2, rq=0.05, delaytime=0.1, fb=0.5;
    var sig, env, pluckEnv, delaySig;
    env = EnvGen.ar(
        Env.adsr(0.01, 0.1, 0.8, 0.5, curve: -4),
        gate: gate,
        doneAction: 2
    );
    pluckEnv = EnvGen.ar(Env.new([1, 0], [dec], [EnvCurve.exp]), gate: gate);
    sig = BPF.ar(WhiteNoise.ar(0.1) * pluckEnv, freq, rq);
    sig = sig * amp * env;

    delaySig = DelayN.ar(sig, 0.2, delaytime);
    delaySig = DelayN.ar(delaySig, 0.2, delaytime) * fb;

    sig = sig + delaySig;

    Out.ar(out, sig ! 2);
}
